     3→import {KeyValue} from "./controller/index.js";
     4→import {Db, DbReqOpts, FilterOptions} from "./controller/interface.js";
     5→import {encodeKey} from "./util.js";
     6→
     7→type Id = Uint8Array | string | number | bigint;
     8→
     9→/**
    10→ * Repository is a high level kv storage
    11→ * This abstract repository is designed in a way to store items with different prefixed
    12→ * Specially when those prefixed data is not available in the object to be stored
    13→ *
    14→ * By default, SSZ-encoded values,
    15→ */
    16→export abstract class PrefixedRepository<P, I extends Id, T> {
    17→  private readonly dbReqOpts: DbReqOpts;
    18→  /** Inclusive range for the minimum key for the bucket */
    19→  private readonly minKey: Uint8Array;
    20→  /** Exclusive range for the maximum key for the bucket */
    21→  private readonly maxKey: Uint8Array;
    22→
    23→  protected constructor(
    24→    protected config: ChainForkConfig,
    25→    protected db: Db,
    26→    protected bucket: number,
    27→    protected type: Type<T>,
    28→    private readonly bucketId: string
    29→  ) {
    30→    this.dbReqOpts = {bucketId: this.bucketId};
    31→    this.minKey = encodeKey(bucket, Buffer.alloc(0));
    32→    this.maxKey = encodeKey(bucket + 1, Buffer.alloc(0));
    33→  }
    34→
    35→  abstract encodeKeyRaw(prefix: P, id: I): Uint8Array;
    36→  abstract decodeKeyRaw(raw: Uint8Array): {prefix: P; id: I};
    37→  /**
    38→   * Max key is inclusive
    39→   * */
    40→  abstract getMaxKeyRaw(prefix: P): Uint8Array;
    41→  /**
    42→   * Min key is inclusive
    43→   * */
    44→  abstract getMinKeyRaw(prefix: P): Uint8Array;
    45→
    46→  protected encodeValue(value: T): Uint8Array {
    47→    return this.type.serialize(value);
    48→  }
    49→
    50→  protected decodeValue(data: Uint8Array): T {
    51→    return this.type.deserialize(data);
    52→  }
    53→
    54→  protected wrapKey(raw: Uint8Array): Uint8Array {
    55→    return encodeKey(this.bucket, raw);
    56→  }
    57→
    58→  protected unwrapKey(key: Uint8Array): Uint8Array {
    59→    return key.slice(BUCKET_LENGTH);
    60→  }
    61→
    62→  // The Id can be inferred from the value
    63→  getId(value: T): I {
    64→    return this.type.hashTreeRoot(value) as I;
    65→  }
    66→
    67→  async get(prefix: P, id: I): Promise<T | null> {
    68→    const key = this.wrapKey(this.encodeKeyRaw(prefix, id));
    69→    const v = await this.db.get(key, this.dbReqOpts);
    70→    return v ? this.decodeValue(v) : null;
    71→  }
    72→
    73→  async getMany(prefix: P, ids: I[]): Promise<(T | undefined)[]> {
    74→    const keys = [];
    75→    for (const id of ids) {
    76→      keys.push(this.wrapKey(this.encodeKeyRaw(prefix, id)));
    77→    }
    78→    const values = await this.db.getMany(keys, this.dbReqOpts);
    79→
    80→    const result = [];
    81→    for (const value of values) {
    82→      result.push(value ? this.decodeValue(value) : undefined);
    83→    }
    84→
    85→    return result;
    86→  }
    87→
    88→  async getManyBinary(prefix: P, ids: I[]): Promise<(Uint8Array | undefined)[]> {
